                nc = c + dc
                if not (0 <= nc < w and grid[r + 1][nc] == color):
                    continue
                # Extend backward from the pair's first endpoint.
                rr, cc = r - 1, c - dc
                ray = []
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    ray.append((rr, cc))
                    rr -= 1
                    cc -= dc
                if len(ray) >= 3:
                    for ar, ac in ray:
                        out[ar][ac] = color
                # Extend forward from the pair's second endpoint.
                rr, cc = r + 2, c + 2 * dc
                ray = []
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    ray.append((rr, cc))
                    rr += 1
                    cc += dc
                if len(ray) >= 3:
                    for ar, ac in ray:
                        out[ar][ac] = color

    # In a 2x2 checkerboard of two colors, continue the diagonal formed by
    # the less frequent color only; the denser color is the motif itself.
    checker = None
    for r in range(h - 1):
