            a,b=grid[r][c],grid[r][c+1]
            if a != background and b != background and a != b and grid[r+1][c] == b and grid[r+1][c+1] == a:
                checker=(a,b)
                break
        if checker:
            break
    if checker:
        counts=Counter(x for row in grid for x in row)
        keep=min(checker,key=lambda x:counts[x])
        for r in range(h):
            for c in range(w):
                if grid[r][c] != background and grid[r][c] != keep:
                    out[r][c]=grid[r][c]
                elif grid[r][c] == background:
                    out[r][c]=background
        # Re-draw only the less frequent diagonal color.
        color=keep
        for r in range(h-1):
            for c in range(w):
                for dc in (-1,1):
                    if 0<=c+dc<w and grid[r][c]==color and grid[r+1][c+dc]==color:
                        rr,cc=r-1,c-dc
                        ray=[]
                        while 0<=rr<h and 0<=cc<w and grid[rr][cc]==background:
                            ray.append((rr,cc));rr-=1;cc-=dc
                        if len(ray)>=3:
                            for ar,ac in ray:out[ar][ac]=color
                        rr,cc=r+2,c+2*dc;ray=[]
                        while 0<=rr<h and 0<=cc<w and grid[rr][cc]==background:
                            ray.append((rr,cc));rr+=1;cc+=dc
                        if len(ray)>=3:
                            for ar,ac in ray:out[ar][ac]=color
    return out


